// Filter & Search Functionality
const searchInput = document.getElementById('searchInput');
const filterButtons = document.querySelectorAll('.filter-btn');
const blogCards = document.querySelectorAll('.blog-card');

let currentCategory = 'all';

// Search functionality
searchInput.addEventListener('input', (e) => {
    const searchTerm = e.target.value.toLowerCase();
    filterCards(searchTerm, currentCategory);
});

// Filter by category
filterButtons.forEach(button => {
    button.addEventListener('click', () => {
        filterButtons.forEach(btn => btn.classList.remove('active'));
        button.classList.add('active');
        currentCategory = button.getAttribute('data-category');
        filterCards(searchInput.value.toLowerCase(), currentCategory);
    });
});

// Filter cards based on search & category
function filterCards(searchTerm, category) {
    blogCards.forEach(card => {
        const cardCategory = card.getAttribute('data-category');
        const title = card.querySelector('.blog-title').textContent.toLowerCase();
        const excerpt = card.querySelector('.blog-excerpt').textContent.toLowerCase();
        const tags = card.querySelectorAll('.blog-tag');
        const tagTexts = Array.from(tags).map(tag => tag.textContent.toLowerCase()).join(' ');

        const matchesCategory = category === 'all' || cardCategory === category;
        const matchesSearch = title.includes(searchTerm) || 
                            excerpt.includes(searchTerm) || 
                            tagTexts.includes(searchTerm);

        card.style.display = (matchesCategory && matchesSearch) ? '' : 'none';
    });
}
